export default function TechMarquee() {
    const sectionRef = useRef<HTMLElement>(null);
    const titleRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        if (titleRef.current) {
            gsap.fromTo(
                titleRef.current,
                { y: 30, opacity: 0 },
                {
                    y: 0,
                    opacity: 1,
                    duration: 0.8,
                    ease: 'power3.out',
                    scrollTrigger: {
                        trigger: titleRef.current,
                        start: 'top 85%',
                        toggleActions: 'play none none reverse'
                    }
                }
            );
        }
    }, []);

    // Double the items for seamless looping
    const marqueeItems = [...techStack, ...techStack];

    return (
        <section ref={sectionRef} className="tech-marquee-section">
            {/* Title */}
            <div ref={titleRef} className="tech-marquee-title" style={{ opacity: 0 }}>
                <p className="tech-marquee-label">Tech Stack</p>
                <h3 className="tech-marquee-heading">Tools I Work With</h3>
            </div>

            {/* Marquee Container */}
            <div className="tech-marquee-container">
                {/* Fade edges */}
                <div className="tech-marquee-fade-left" />
                <div className="tech-marquee-fade-right" />

                {/* Scrolling track */}
                <div className="tech-marquee-track">
                    {marqueeItems.map((tech, index) => (
                        <div key={`${tech.name}-${index}`} className="tech-marquee-item">
                            <div className="tech-marquee-icon-wrapper">
                                {tech.icon}
                            </div>
                            <span className="tech-marquee-name">{tech.name}</span>
                        </div>
                    ))}
                </div>
            </div>
        </section>
    );
}
